1	//! Standalone, executable regression target for layered subcommand dispatch
2	//! with external-plugin catch-alls at two levels.
3	//!
4	//! Unlike the tests under `tests/derive/`, this file is a self-contained test
5	//! target that defines its own derived CLI and observes every result solely
6	//! through the public `clap::Parser` API via `Cli::try_parse_from` (argv0
7	//! included): successful structures, typed errors, and rendered help text.
8	//!
9	//! Scenario under test:
10	//! * root command `tool` with a default config path and repeatable
11	//!   `--define` items, both global so they parse next to any subcommand;
12	//! * declared subcommands `serve` and `check`, plus a root external
13	//!   catch-all for root-level plugins;
14	//! * `serve` declares `worker` and has its own external catch-all for serve
15	//!   plugins, so an unknown name under `serve` never escapes to the root;
16	//! * `worker` requires a unique decimal `--port` in 1..=65535, two mutually
17	//!   exclusive protocol switches (`--tcp`/`--udp`), and verbatim trailing
18	//!   arguments after its own `--`;
19	//! * `check` takes only an optional path and `--strict` and must never accept
20	//!   arguments owned by `serve` or `worker`;
21	//! * globals may appear before or after the root/serve/worker/check tokens;
22	//!   explicit config overrides the default and defines keep occurrence order;
23	//! * declared subcommands win over external capture, and once an external
24	//!   name is selected every following token belongs to that plugin;
25	//! * a root-level `--` forces the next token to be the root plugin name, a
26	//!   serve-level `--` forces the next token to be the serve plugin name, while
27	//!   the separator inside `worker` only produces trailing arguments;
28	//! * validation failures name the triggering token (and argument), use the
29	//!   distinct error kinds for missing, invalid, conflicting and unknown
30	//!   tokens, and never leave a partially populated match readable;
31	//! * help for root, serve, worker and check succeeds even while required
32	//!   values are missing and shows only that level's surface;
33	//! * a fixed sequence of root-plugin success, serve-plugin success, invalid
34	//!   input, worker success and help requests is mutually isolated, and merely
35	//!   moving the global arguments around changes neither the parsed structure,
36	//!   trailing order, error usage nor the order seen in help.
37	#![cfg(feature = "derive")]
38	#![cfg(feature = "help")]
39	#![cfg(feature = "usage")]
40	
41	use clap::Args;
42	use clap::Parser;
43	use clap::Subcommand;
44	use clap::error::ErrorKind;
45	
46	/// Strict decimal port parser: digits only, range 1..=65535.
47	///
48	/// Signs, hex prefixes, whitespace and empty values are all rejected instead
49	/// of being normalized by `u16::from_str`.
50	fn parse_port(raw: &str) -> Result<u16, String> {
51	    if raw.is_empty() || !raw.bytes().all(|b| b.is_ascii_digit()) {
52	        return Err(format!(
53	            "invalid port `{raw}`: expected a decimal number between 1 and 65535"
54	        ));
55	    }
56	    match raw.parse::<u32>() {
57	        Ok(port) if (1..=65535).contains(&port) => Ok(port as u16),
58	        _ => Err(format!(
59	            "invalid port `{raw}`: expected a decimal number between 1 and 65535"
60	        )),
61	    }
62	}
63	
64	fn parse_define(raw: &str) -> Result<String, String> {
65	    if raw.contains('=') {
66	        Ok(raw.to_owned())
67	    } else {
68	        Err(format!("invalid define `{raw}`: expected key=value"))
69	    }
70	}
71	
72	#[derive(Parser, Debug, Clone, PartialEq)]
73	#[command(
74	    name = "tool",
75	    after_help = "External plugins: any other <COMMAND> is captured as a root plugin."
76	)]
77	struct Cli {
78	    #[arg(
79	        long,
80	        global = true,
81	        default_value = "builtin.toml",
82	        value_name = "path"
83	    )]
84	    config: String,
85	    #[arg(long, global = true, value_name = "key=value", value_parser = parse_define)]
86	    define: Vec<String>,
87	    #[command(subcommand)]
88	    command: Commands,
89	}
90	
91	#[derive(Subcommand, Debug, Clone, PartialEq)]
92	enum Commands {
93	    Serve(ServeArgs),
94	    Check(CheckArgs),
95	    #[command(external_subcommand)]
96	    External(Vec<String>),
97	}
98	
99	#[derive(Args, Debug, Clone, PartialEq)]
100	#[command(after_help = "External plugins: any other <COMMAND> is captured as a serve plugin.")]
101	struct ServeArgs {
102	    #[command(subcommand)]
103	    command: ServeCommands,
104	}
105	
106	#[derive(Subcommand, Debug, Clone, PartialEq)]
107	enum ServeCommands {
108	    Worker(WorkerArgs),
109	    #[command(external_subcommand)]
110	    External(Vec<String>),
111	}
112	
113	#[derive(Args, Debug, Clone, PartialEq)]
114	struct WorkerArgs {
115	    #[arg(long, value_name = "port", required = true, value_parser = parse_port)]
116	    port: u16,
117	    #[arg(long, conflicts_with = "udp")]
118	    tcp: bool,
119	    #[arg(long, conflicts_with = "tcp")]
120	    udp: bool,
121	    #[arg(last = true)]
122	    trailing: Vec<String>,
123	}
124	
125	#[derive(Args, Debug, Clone, PartialEq)]
126	struct CheckArgs {
127	    path: Option<String>,
128	    #[arg(long)]
129	    strict: bool,
130	}
131	
132	fn parse(argv: &[&str]) -> Result<Cli, clap::Error> {
133	    Cli::try_parse_from(argv)
134	}
135	
136	fn root_external_ok(argv: &[&str]) -> (String, Vec<String>, Vec<String>) {
137	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
138	    let Commands::External(tokens) = cli.command else {
139	        panic!(
140	            "expected root external subcommand for {argv:?}, got {:?}",
141	            cli.command
142	        );
143	    };
144	    assert!(
145	        !tokens.is_empty(),
146	        "external capture must always include the command name: {argv:?}"
147	    );
148	    (cli.config, cli.define, tokens)
149	}
150	
151	fn serve_external_ok(argv: &[&str]) -> (String, Vec<String>, Vec<String>) {
152	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
153	    let Commands::Serve(serve) = cli.command else {
154	        panic!("expected `serve` for {argv:?}, got {:?}", cli.command);
155	    };
156	    let ServeCommands::External(tokens) = serve.command else {
157	        panic!(
158	            "expected serve external subcommand for {argv:?}, got {:?}",
159	            serve.command
160	        );
161	    };
162	    assert!(
163	        !tokens.is_empty(),
164	        "external capture must always include the command name: {argv:?}"
165	    );
166	    (cli.config, cli.define, tokens)
167	}
168	
169	fn worker_ok(argv: &[&str]) -> (String, Vec<String>, WorkerArgs) {
170	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
171	    let Commands::Serve(serve) = cli.command else {
172	        panic!(
173	            "expected `serve worker` for {argv:?}, got {:?}",
174	            cli.command
175	        );
176	    };
177	    let ServeCommands::Worker(worker) = serve.command else {
178	        panic!("expected `worker` for {argv:?}, got {:?}", serve.command);
179	    };
180	    (cli.config, cli.define, worker)
181	}
182	
183	fn check_ok(argv: &[&str]) -> (String, Vec<String>, CheckArgs) {
184	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
185	    let Commands::Check(check) = cli.command else {
186	        panic!("expected `check` for {argv:?}, got {:?}", cli.command);
187	    };
188	    (cli.config, cli.define, check)
189	}
190	
191	/// Render an error while dropping the optional backtrace appended by clap's
192	/// `debug` feature. The backtrace captures host paths and frame line numbers
193	/// and is not part of the user-facing help or error output under test.
194	fn rendered(err: &clap::Error) -> String {
195	    let text = err.to_string();
196	    match text.split_once("\nBacktrace:") {
197	        Some((head, _)) => head.trim_end().to_owned(),
198	        None => text,
199	    }
200	}
201	
202	fn fail_kind(argv: &[&str]) -> (ErrorKind, String) {
203	    match parse(argv) {
204	        Ok(cli) => panic!("expected failure for {argv:?}, got {cli:?}"),
205	        Err(err) => (err.kind(), rendered(&err)),
206	    }
207	}
208	
209	fn help_text(argv: &[&str]) -> String {
210	    let err = parse(argv).expect_err("help is reported as a DisplayHelp error");
211	    assert_eq!(err.kind(), ErrorKind::DisplayHelp, "{argv:?}");
212	    rendered(&err)
213	}
