246	#[test]
247	fn missing_subcommand_shows_that_levels_help_without_dispatching() {
248	    // Neither level may guess a plugin name when no token is present.
249	    let (kind, _) = fail_kind(&["tool"]);
250	    assert_eq!(kind, ErrorKind::DisplayHelpOnMissingArgumentOrSubcommand);
251	    let (kind, msg) = fail_kind(&["tool", "serve"]);
252	    assert_eq!(kind, ErrorKind::DisplayHelpOnMissingArgumentOrSubcommand);
253	    assert!(msg.contains("tool serve"), "{msg}");
254	    assert!(msg.contains("worker"), "{msg}");
255	}
