372	// ---- root- and serve-level `--` -------------------------------------------
373	
374	#[test]
375	fn root_double_dash_forces_next_token_to_be_root_plugin_name() {
376	    let (config, define, tokens) =
377	        root_external_ok(&["tool", "--config", "c.toml", "--", "--flag", "x", "--", ""]);
378	    assert_eq!(config, "c.toml");
379	    assert_eq!(define, Vec::<String>::new());
380	    assert_eq!(tokens, vec!["--flag", "x", "--", ""]);
381	
382	    // Declared names after the separator are plugin names, not commands.
383	    let (_, _, tokens) = root_external_ok(&["tool", "--", "serve", "x"]);
384	    assert_eq!(tokens, vec!["serve", "x"]);
385	    let (_, _, tokens) = root_external_ok(&["tool", "--", "check"]);
386	    assert_eq!(tokens, vec!["check"]);
387	    let (_, _, tokens) = root_external_ok(&["tool", "--", "", "rest"]);
388	    assert_eq!(tokens, vec!["", "rest"]);
389	}
