391	#[test]
392	fn serve_double_dash_forces_next_token_to_be_serve_plugin_name() {
393	    let (config, define, tokens) = serve_external_ok(&[
394	        "tool", "serve", "--define", "a=1", "--", "worker", "--port", "1",
395	    ]);
396	    assert_eq!(config, "builtin.toml");
397	    assert_eq!(define, vec!["a=1"]);
398	    assert_eq!(tokens, vec!["worker", "--port", "1"]);
399	
400	    let (_, _, tokens) = serve_external_ok(&["tool", "serve", "--", "--flag"]);
401	    assert_eq!(tokens, vec!["--flag"]);
402	    let (_, _, tokens) = serve_external_ok(&["tool", "serve", "--", "", "x"]);
403	    assert_eq!(tokens, vec!["", "x"]);
