408	#[test]
409	fn worker_requires_port_on_success_path_and_accepts_bounds() {
410	    let (_, _, worker) = worker_ok(&["tool", "serve", "worker", "--port", "1", "--tcp"]);
411	    assert_eq!(
412	        worker,
413	        WorkerArgs {
414	            port: 1,
415	            tcp: true,
416	            udp: false,
417	            trailing: vec![],
418	        }
419	    );
420	
421	    let (_, _, worker) = worker_ok(&["tool", "serve", "worker", "--port=65535", "--udp"]);
422	    assert_eq!(worker.port, 65535);
423	    assert!(worker.udp);
424	
425	    // Leading zeroes are still plain decimal digits.
426	    let (_, _, worker) = worker_ok(&["tool", "serve", "worker", "--port", "080"]);
427	    assert_eq!(worker.port, 80);
428	}
