430	#[test]
431	fn worker_trailing_after_separator_is_verbatim_and_never_redispatches() {
432	    let (config, define, worker) = worker_ok(&[
433	        "tool", "serve", "worker", "--port", "8080", "--tcp", "--", "plug", "--tcp", "--udp",
434	        "--port", "9090", "worker", "serve", "--", "",
435	    ]);
436	    assert_eq!(config, "builtin.toml");
437	    assert_eq!(define, Vec::<String>::new());
