449	#[test]
450	fn worker_trailing_requires_the_separator() {
451	    // Without `--`, worker has no positional slot and a bare token is rejected
452	    // rather than silently treated as trailing data.
453	    let (kind, msg) = fail_kind(&["tool", "serve", "worker", "--port", "8080", "plug"]);
454	    assert_eq!(kind, ErrorKind::UnknownArgument);
455	    assert!(msg.contains("'plug'"), "{msg}");
