524	#[test]
525	fn missing_port_fails_in_worker_context() {
526	    let (kind, msg) = fail_kind(&["tool", "serve", "worker"]);
527	    assert_eq!(kind, ErrorKind::MissingRequiredArgument);
528	    assert!(msg.contains("--port"), "{msg}");
529	    assert!(msg.contains("tool serve worker"), "{msg}");
530	    assert!(!msg.contains("tool check"), "{msg}");
531	
532	    // A global missing value must not masquerade as the missing port, and the
533	    // port is still reported as missing once such input is fixed.
534	    let (kind, msg) = fail_kind(&[
535	        "tool", "--define", "a=1", "serve", "--config", "c.toml", "worker",
536	    ]);
537	    assert_eq!(kind, ErrorKind::MissingRequiredArgument);
538	    assert!(msg.contains("--port"), "{msg}");
