541	#[test]
542	fn out_of_range_port_is_an_invalid_value() {
543	    for argv in [
544	        &["tool", "serve", "worker", "--port", "0"][..],
545	        &["tool", "serve", "worker", "--port", "65536"][..],
546	        &["tool", "serve", "worker", "--port=99999999999999999999"][..],
547	    ] {
548	        let bad = argv[argv.len() - 1].trim_start_matches("--port=");
549	        let (kind, msg) = fail_kind(argv);
550	        assert_eq!(kind, ErrorKind::ValueValidation, "{argv:?}");
551	        assert!(msg.contains(bad), "{argv:?}: {msg}");
552	        assert!(msg.contains("--port"), "{argv:?}: {msg}");
553	    }
554	}
