556	#[test]
557	fn non_numeric_port_is_an_invalid_value_not_an_unknown_token() {
558	    for argv in [
559	        &["tool", "serve", "worker", "--port", "abc"][..],
560	        &["tool", "serve", "worker", "--port", "1x"][..],
561	        &["tool", "serve", "worker", "--port", "+80"][..],
562	        &["tool", "serve", "worker", "--port=0x10"][..],
563	        &["tool", "serve", "worker", "--port="][..],
564	    ] {
565	        let (kind, msg) = fail_kind(argv);
566	        assert_eq!(kind, ErrorKind::ValueValidation, "{argv:?}");
567	        assert!(msg.contains("--port"), "{argv:?}: {msg}");
568	    }
569	
570	    // A detached negative number is consumed by the option lexer as a flag and
571	    // therefore reported as the unknown token it actually is.
572	    let (kind, msg) = fail_kind(&["tool", "serve", "worker", "--port", "-1"]);
573	    assert_eq!(kind, ErrorKind::UnknownArgument);
574	    assert!(msg.contains("-1"), "{msg}");
575	    assert!(msg.contains("tool serve worker"), "{msg}");
576	
577	    // The attached form instead reaches the parser as the port's value.
578	    let (kind, msg) = fail_kind(&["tool", "serve", "worker", "--port=-1"]);
579	    assert_eq!(kind, ErrorKind::ValueValidation);
580	    assert!(msg.contains("'-1'"), "{msg}");
581	}
