    let (kind, msg) = fail_kind(&["tool", "serve", "worker", "--port", "80", "--bogus"]);
    assert_eq!(kind, ErrorKind::UnknownArgument);
    assert!(msg.contains("--bogus"), "{msg}");
    assert!(msg.contains("tool serve worker"), "{msg}");
