1	//! Standalone, executable regression target for external-plugin dispatch.
2	//!
3	//! Unlike the tests under `tests/derive/`, this file is a self-contained test
4	//! target that does not depend on any private test module from a candidate
5	//! branch. It defines its own derived CLI and observes every result solely
6	//! through the public `clap::Parser` API via `Cli::try_parse_from` (argv0
7	//! included): successful structures, typed errors, and rendered help text.
8	//!
9	//! Scenario under test:
10	//! * root command `tool` with a declared `run` subcommand (alias `r`) and an
11	//!   external-subcommand catch-all for plugins;
12	//! * root-level default config path and repeatable `--define` items that only
13	//!   parse while the root command is active;
14	//! * every token at or after the external command name is captured verbatim,
15	//!   including option-like tokens, declared subcommand names, a second `--`,
16	//!   and empty strings;
17	//! * a root-level `--` forces the next token to be the external command name,
18	//!   while `--` after `run` only produces `run` trailing arguments;
19	//! * validation failures name the triggering token and the most specific
20	//!   command and never leave a partially populated match readable;
21	//! * root and `run` help succeed while required values are missing;
22	//! * a fixed sequence of success, failure, success, and help parses is
23	//!   mutually isolated.
24	#![cfg(feature = "derive")]
25	#![cfg(feature = "help")]
26	#![cfg(feature = "usage")]
27	
28	use clap::Args;
29	use clap::Parser;
30	use clap::Subcommand;
31	use clap::error::ErrorKind;
32	
33	fn parse_define(raw: &str) -> Result<String, String> {
34	    if raw.contains('=') {
35	        Ok(raw.to_owned())
36	    } else {
37	        Err(format!("invalid define `{raw}`: expected key=value"))
38	    }
39	}
40	
41	#[derive(Parser, Debug, PartialEq)]
42	#[command(
43	    name = "tool",
44	    about = "Root command dispatching to built-in and plugin subcommands",
45	    override_usage = "tool [OPTIONS] <COMMAND>"
46	)]
47	struct Cli {
48	    #[arg(
49	        long,
50	        global = true,
51	        default_value = "builtin.toml",
52	        value_name = "path"
53	    )]
54	    config: String,
55	    #[arg(long, global = true, value_name = "key=value", value_parser = parse_define)]
56	    define: Vec<String>,
57	    #[command(subcommand)]
58	    command: Commands,
59	}
60	
61	#[derive(Subcommand, Debug, PartialEq)]
62	enum Commands {
63	    #[command(about = "Run a job", alias = "r")]
64	    Run(RunArgs),
65	    #[command(external_subcommand)]
66	    External(Vec<String>),
67	}
68	
69	#[derive(Args, Debug, PartialEq)]
70	#[command(override_usage = "tool run [OPTIONS] --output <path> [-- <TRAILING>...]")]
71	struct RunArgs {
72	    #[arg(long, value_name = "path", required = true)]
73	    output: String,
74	    #[arg(last = true)]
75	    trailing: Vec<String>,
76	}
77	
78	fn parse(argv: &[&str]) -> Result<Cli, clap::Error> {
79	    Cli::try_parse_from(argv)
80	}
81	
82	fn external_ok(argv: &[&str]) -> (String, Vec<String>, Vec<String>) {
83	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
84	    let Commands::External(tokens) = cli.command else {
85	        panic!(
86	            "expected external subcommand for {argv:?}, got {:?}",
87	            cli.command
88	        );
89	    };
90	    assert!(
91	        !tokens.is_empty(),
92	        "external capture must always include the command name: {argv:?}"
93	    );
94	    (cli.config, cli.define, tokens)
95	}
96	
97	fn run_ok(argv: &[&str]) -> (String, Vec<String>, RunArgs) {
98	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
99	    let Commands::Run(run) = cli.command else {
100	        panic!("expected `run` parse for {argv:?}, got {:?}", cli.command);
101	    };
102	    (cli.config, cli.define, run)
103	}
104	
105	/// Render an error while dropping the optional backtrace appended by clap's
106	/// `debug` feature. The backtrace captures host paths and frame line numbers
107	/// and is not part of the user-facing help or error output under test.
108	fn rendered(err: &clap::Error) -> String {
109	    let text = err.to_string();
110	    match text.split_once("\nBacktrace:") {
111	        Some((head, _)) => head.trim_end().to_owned(),
112	        None => text,
113	    }
114	}
115	
116	fn fail_kind(argv: &[&str]) -> (ErrorKind, String) {
117	    match parse(argv) {
118	        Ok(cli) => panic!("expected failure for {argv:?}, got {cli:?}"),
119	        Err(err) => {
120	            let kind = err.kind();
121	            (kind, rendered(&err))
122	        }
123	    }
124	}
