305	        assert_eq!(kind, ErrorKind::MissingRequiredArgument, "{argv:?}");
306	        assert!(msg.contains("--output"), "{argv:?}: {msg}");
307	        // The error must identify the most specific command, not the root.
308	        assert!(msg.contains("tool run"), "{argv:?}: {msg}");
309	        assert!(
310	            !msg.contains("tool [OPTIONS] <COMMAND>"),
311	            "{argv:?} unexpectedly used root usage:\n{msg}"
312	        );
313	    }
314	}
315	
316	#[test]
317	fn duplicate_output_fails_for_both_run_names() {
318	    for argv in [
319	        &["tool", "run", "--output", "a", "--output", "b"][..],
320	        &["tool", "r", "--output", "a", "--output", "b"][..],
321	    ] {
322	        let (kind, msg) = fail_kind(argv);
323	        assert_eq!(kind, ErrorKind::ArgumentConflict, "{argv:?}");
324	        assert!(msg.contains("--output"), "{argv:?}: {msg}");
325	        assert!(msg.contains("tool run"), "{argv:?}: {msg}");
326	    }
327	}
328	
329	#[test]
330	fn duplicate_root_config_fails_at_root() {
331	    let argv = ["tool", "--config", "a", "--config", "b", "plug"];
332	    let (kind, msg) = fail_kind(&argv);
333	    assert_eq!(kind, ErrorKind::ArgumentConflict);
334	    assert!(msg.contains("--config"), "{msg}");
335	    assert!(msg.contains("tool [OPTIONS] <COMMAND>"), "{msg}");
336	}
337	
338	#[test]
339	fn unknown_root_option_fails_on_triggering_token_before_external_name() {
340	    for argv in [
341	        &["tool", "--bogus", "plug"][..],
342	        &["tool", "--config", "c.toml", "--bogus", "plug"][..],
343	    ] {
344	        let (kind, msg) = fail_kind(argv);
345	        assert_eq!(kind, ErrorKind::UnknownArgument, "{argv:?}");
346	        assert!(msg.contains("--bogus"), "{argv:?}: {msg}");
347	        assert!(msg.contains("tool [OPTIONS] <COMMAND>"), "{argv:?}: {msg}");
348	    }
349	
350	    let (kind, msg) = fail_kind(&["tool", "-x", "plug"]);
351	    assert_eq!(kind, ErrorKind::UnknownArgument);
352	    assert!(msg.contains("-x"), "{msg}");
353	}
354	
355	#[test]
356	fn unknown_run_option_fails_within_run_context() {
357	    let argv = ["tool", "run", "--output", "o", "--bogus"];
358	    let (kind, msg) = fail_kind(&argv);
359	    assert_eq!(kind, ErrorKind::UnknownArgument);
360	    assert!(msg.contains("--bogus"), "{msg}");
361	    assert!(msg.contains("tool run"), "{msg}");
362	}
363	
364	#[test]
365	fn missing_option_value_fails_on_the_option() {
366	    for argv in [
367	        &["tool", "--config"][..],
368	        &["tool", "--define"][..],
369	        &["tool", "--config", "c.toml", "--define"][..],
370	    ] {
371	        let (kind, msg) = fail_kind(argv);
372	        assert_eq!(kind, ErrorKind::InvalidValue, "{argv:?}");
373	        let needle = if argv.last() == Some(&"--config") {
374	            "--config"
375	        } else {
376	            "--define"
377	        };
378	        assert!(msg.contains(needle), "{argv:?}: {msg}");
379	    }
380	}
381	
382	#[test]
383	fn invalid_define_fails_on_value_before_external_name() {
384	    for argv in [
385	        &["tool", "--define", "nokey", "plug"][..],
386	        &["tool", "--define=nokey"][..],
387	    ] {
388	        let (kind, msg) = fail_kind(argv);
389	        assert_eq!(kind, ErrorKind::ValueValidation, "{argv:?}");
390	        assert!(msg.contains("nokey"), "{argv:?}: {msg}");
391	        // The error names both the offending value and the argument it belongs to.
392	        assert!(msg.contains("--define"), "{argv:?}: {msg}");
393	    }
394	}
395	
396	#[test]
397	fn invalid_define_after_external_name_is_captured_as_data() {
398	    let (config, define, tokens) = external_ok(&["tool", "plug", "--define", "nokey"]);
399	    assert_eq!(config, "builtin.toml");
400	    assert_eq!(define, Vec::<String>::new());
401	    assert_eq!(tokens, vec!["plug", "--define", "nokey"]);
402	}
403	
404	// ---- help -----------------------------------------------------------------
405	
406	#[test]
407	fn root_help_succeeds_without_subcommand_or_required_values() {
408	    let err = parse(&["tool", "--help"]).unwrap_err();
409	    assert_eq!(err.kind(), ErrorKind::DisplayHelp);
410	    let help = rendered(&err);
411	    for needle in ["--config", "builtin.toml", "--define", "key=value", "run"] {
412	        assert!(help.contains(needle), "root help missing {needle}:\n{help}");
413	    }
414	    assert!(
415	        !help.contains("--output"),
416	        "run option leaked into root help:\n{help}"
417	    );
418	    assert!(!help.to_ascii_lowercase().contains("error"), "{help}");
419	}
