421	#[test]
422	fn run_help_succeeds_while_output_is_missing() {
423	    for argv in [&["tool", "run", "--help"][..], &["tool", "r", "--help"][..]] {
424	        let err = parse(argv).unwrap_err();
425	        assert_eq!(err.kind(), ErrorKind::DisplayHelp, "{argv:?}");
426	        let help = rendered(&err);
427	        assert!(help.contains("--output"), "{argv:?}: {help}");
428	        assert!(help.contains("tool run"), "{argv:?}: {help}");
429	        assert!(help.contains("TRAILING"), "{argv:?}: {help}");
430	        assert!(
431	            !help.to_ascii_lowercase().contains("error"),
432	            "{argv:?}: {help}"
433	        );
434	    }
435	}
436	
437	// ---- fixed-order isolation sequence ---------------------------------------
438	
439	#[test]
440	fn fixed_order_sequence_success_failure_success_help_is_isolated() {
441	    // Capture a clean baseline help up front; the trailing help requests must
442	    // render the same text after the intervening failure.
443	    let clean_root_help = rendered(&parse(&["tool", "--help"]).unwrap_err());
444	    let clean_run_help = rendered(&parse(&["tool", "run", "--help"]).unwrap_err());
445	
446	    // 1. External success: explicit root state plus verbatim plugin tokens.
447	    let (config, define, tokens) = external_ok(&[
448	        "tool",
449	        "--config",
450	        "custom.toml",
451	        "--define",
452	        "a=1",
453	        "plug",
454	        "--flag",
455	        "run",
456	        "--",
457	        "",
458	    ]);
459	    assert_eq!(config, "custom.toml");
460	    assert_eq!(define, vec!["a=1"]);
461	    assert_eq!(tokens, vec!["plug", "--flag", "run", "--", ""]);
462	
463	    // 2. Invalid root input fails categorically on the offending token.
464	    let err = parse(&["tool", "--define", "bogus", "plug"]).unwrap_err();
465	    assert_eq!(err.kind(), ErrorKind::ValueValidation);
466	    assert!(rendered(&err).contains("bogus"));
467	
468	    // 3. `run` success is unaffected by either preceding call: root defaults
469	    //    are restored and no earlier tokens leak into trailing.
470	    let (config, define, run) = run_ok(&["tool", "r", "--output", "o", "--", "z", "--config"]);
471	    assert_eq!(config, "builtin.toml");
472	    assert_eq!(define, Vec::<String>::new());
473	    assert_eq!(
474	        run,
475	        RunArgs {
476	            output: "o".to_owned(),
477	            trailing: vec!["z".to_owned(), "--config".to_owned()],
478	        }
479	    );
480	
481	    // 4. Help requests still succeed and carry no trace of the failed call.
482	    let root_help = parse(&["tool", "--help"]).unwrap_err();
483	    assert_eq!(root_help.kind(), ErrorKind::DisplayHelp);
484	    let root_help = rendered(&root_help);
485	    assert_eq!(root_help, clean_root_help);
486	    assert!(!root_help.contains("bogus"), "{root_help}");
487	    assert!(!root_help.contains("--output"), "{root_help}");
488	
489	    let run_help = parse(&["tool", "run", "--help"]).unwrap_err();
490	    assert_eq!(run_help.kind(), ErrorKind::DisplayHelp);
491	    let run_help = rendered(&run_help);
492	    assert_eq!(run_help, clean_run_help);
493	    assert!(!run_help.contains("bogus"), "{run_help}");
494	    assert!(run_help.contains("--output"), "{run_help}");
495	}
