    assert_eq!(run_help.kind(), ErrorKind::DisplayHelp);
    let run_help = rendered(&run_help);
    assert_eq!(run_help, clean_run_help);
    assert!(!run_help.contains("bogus"), "{run_help}");
    assert!(run_help.contains("--output"), "{run_help}");
}

