#![cfg(feature = "derive")]
#![cfg(feature = "help")]
#![cfg(feature = "usage")]

use clap::Args;
use clap::Parser;
use clap::Subcommand;
use clap::error::ErrorKind;

fn parse_port(raw: &str) -> Result<u16, String> {
    if raw.is_empty() || !raw.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!(
            "invalid port `{raw}`: expected a decimal number between 1 and 65535"
        ));
    }
    match raw.parse::<u32>() {
        Ok(port) if (1..=65535).contains(&port) => Ok(port as u16),
        _ => Err(format!(
            "invalid port `{raw}`: expected a decimal number between 1 and 65535"
        )),
    }
}

fn parse_define(raw: &str) -> Result<String, String> {
    if raw.is_empty() {
        return Err("invalid define ``: expected key=value".to_owned());
    }
    let mut split = raw.splitn(2, '=');
    let key = split.next().unwrap();
    let val = split.next();
    match val {
        Some(v) if !key.is_empty() && !v.is_empty() && !v.contains('=') => Ok(raw.to_owned()),
        _ => Err(format!("invalid define `{raw}`: expected key=value")),
    }
}

#[derive(Parser, Debug, Clone, PartialEq)]
#[command(name = "tool")]
struct Cli {
    #[arg(
        long,
        global = true,
        default_value = "builtin.toml",
        value_name = "path"
    )]
    config: String,
    #[arg(long, global = true, value_name = "key=value", value_parser = parse_define, allow_hyphen_values = true)]
    define: Vec<String>,
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug, Clone, PartialEq)]
enum Commands {
    Serve(ServeArgs),
    Check(CheckArgs),
    #[command(external_subcommand)]
    External(Vec<String>),
}

#[derive(Args, Debug, Clone, PartialEq)]
struct ServeArgs {
    #[command(subcommand)]
    command: ServeCommands,
}

#[derive(Subcommand, Debug, Clone, PartialEq)]
enum ServeCommands {
    Worker(WorkerArgs),
    #[command(external_subcommand)]
    External(Vec<String>),
}

#[derive(Args, Debug, Clone, PartialEq)]
struct WorkerArgs {
    #[arg(long, value_name = "port", required = true, value_parser = parse_port, allow_hyphen_values = true)]
    port: u16,
    #[arg(long, conflicts_with = "udp")]
    tcp: bool,
    #[arg(long, conflicts_with = "tcp")]
    udp: bool,
    #[arg(last = true)]
    trailing: Vec<String>,
}

#[derive(Args, Debug, Clone, PartialEq)]
struct CheckArgs {
    path: Option<String>,
    #[arg(long)]
    strict: bool,
}

fn probe(argv: &[&str]) {
    match Cli::try_parse_from(argv) {
        Ok(cli) => println!("OK   {argv:?} => {cli:?}"),
        Err(err) => {
            let text = err.to_string();
            let head = text.split_once("\n\n").map_or(text.as_str(), |(h, _)| h);
            println!("FAIL {argv:?} => {:?} :: {head}", err.kind());
        }
    }
}

#[test]
fn probe_all() {
    // define successes
    probe(&["tool", "--define", "a=1", "plug"]);
    probe(&["tool", "--define=a=1", "plug"]);
    probe(&["tool", "--define", "a = 1", "plug"]); // whitespace -> should fail
    probe(&["tool", "serve", "worker", "--port", "80", "--define", "k= v"]);

    // define failures
    probe(&["tool", "--define", "nokey", "plug"]);
    probe(&["tool", "--define=nokey"]);
    probe(&["tool", "--define", "=1"]);
    probe(&["tool", "--define", "a="]);
    probe(&["tool", "--define", "="]);
    probe(&["tool", "--define", "a=b=c"]);
    probe(&["tool", "--define", " a=1"]);
    probe(&["tool", "--define", "a=1 "]);
    probe(&["tool", "--define", " " ]);
    probe(&["tool", "--define="]);
    probe(&["tool", "--define"]);
    probe(&["tool", "--define", "--config", "x", "plug"]);
    probe(&["tool", "check", "--define", "bad"]);

    // define after external name
    probe(&["tool", "plug", "--define", "a=b=c"]);
    probe(&["tool", "serve", "plug", "--define", "=x"]);

    // port negatives
    probe(&["tool", "serve", "worker", "--port", "-1"]);
    probe(&["tool", "serve", "worker", "--port=-1"]);
    probe(&["tool", "serve", "worker", "--port", "+80"]);
    probe(&["tool", "serve", "worker", "--port=0x10"]);
    probe(&["tool", "serve", "worker", "--port="]);
    probe(&["tool", "serve", "worker", "--port", "8 0"]);
    probe(&["tool", "serve", "worker", "--port", "8_0"]);
    probe(&["tool", "serve", "worker", "--port", "65536"]);
    probe(&["tool", "serve", "worker", "--port", "99999999999999"]);
    probe(&["tool", "serve", "worker", "--port", "0"]);
    probe(&["tool", "serve", "worker", "--port", ""]);
    probe(&["tool", "serve", "worker", "--port"]);
    probe(&["tool", "serve", "worker", "--port", "80", "--port", "81"]);

    // check does not know port
    probe(&["tool", "check", "--port", "80"]);

    // external success
    probe(&["tool", "plug", "--define", "a=1", "--port", "0"]);
    probe(&["tool", "serve", "plug", "x"]);

    // help
    probe(&["tool", "--help"]);
}

