use clap::Args;
use clap::Parser;
use clap::Subcommand;
use clap::error::ErrorKind;

fn parse_port(raw: &str) -> Result<u16, String> {
    if raw.is_empty() || !raw.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!(
            "invalid port `{raw}`: expected a decimal number between 1 and 65535"
        ));
    }
    match raw.parse::<u32>() {
        Ok(port) if (1..=65535).contains(&port) => Ok(port as u16),
        _ => Err(format!(
            "invalid port `{raw}`: expected a decimal number between 1 and 65535"
        )),
    }
}

fn parse_define(raw: &str) -> Result<String, String> {
    if raw.is_empty() {
        return Err("invalid define ``: expected key=value".to_owned());
    }
    let mut split = raw.splitn(2, '=');
    let key = split.next().unwrap();
    let val = split.next();
    match val {
        Some(v) if !key.is_empty() && !v.is_empty() && !v.contains('=') => Ok(raw.to_owned()),
        _ => Err(format!("invalid define `{raw}`: expected key=value")),
    }
}

