    probe(&["tool", "--define", " a=1", "plug"]);
    probe(&["tool", "--define", " a=1", "check"]);
    probe(&["tool", "--define", " a=1", "serve", "worker"]);
    probe(&["tool", "--define", "a=1 ", "plug"]);
    probe(&["tool", "--define", "a=1 ", "serve", "worker"]);
    // internal whitespace inside value is allowed
    probe(&["tool", "--define", "a=b c", "plug"]);
    probe(&["tool", "--define", "k = v", "plug"]);
    // attached forms
    probe(&["tool", "--define==1", "plug"]);
    probe(&["tool", "--define=a=", "plug"]);
    probe(&["tool", "--define==", "plug"]);
    // tab/newline
    probe(&["tool", "--define", "a=1\n", "plug"]);
    // empty
    probe(&["tool", "--define", "", "plug"]);
    // two valid then invalid
    probe(&["tool", "--define", "a=1", "--define", "b=2", "--define", "c=", "plug"]);
    // define before serve-plugin success
    probe(&["tool", "--define", "a=1", "serve", "plug", "x"]);
}

