#[test]
fn worker_port_accepts_decimal_bounds_and_leading_zeroes() {
    for argv in [
        &["tool", "serve", "worker", "--port", "1", "--tcp"][..],
        &["tool", "serve", "worker", "--port=65535", "--udp"][..],
        &["tool", "serve", "worker", "--port", "080"][..],
    ] {
        let (_, _, worker) = worker_ok(argv);
        assert_eq!(
            worker.port,
            argv.iter()
                .find_map(|t| t.trim_start_matches("--port=").parse::<u16>().ok())
                .or_else(|| {
                    let i = argv.iter().position(|t| *t == "--port")?;
                    argv[i + 1].parse::<u16>().ok()
                })
                .unwrap(),
            "{argv:?}"
        );
    }

    let (_, _, worker) = worker_ok(&["tool", "serve", "worker", "--port", "1"]);
    assert_eq!(worker.port, 1);
    assert!(!worker.tcp);
    assert!(!worker.udp);

    let (_, _, worker) = worker_ok(&["tool", "serve", "worker", "--port=65535"]);
    assert_eq!(worker.port, 65535);

    let (_, _, worker) = worker_ok(&["tool", "serve", "worker", "--port", "080"]);
    assert_eq!(worker.port, 80);
}

